import styled from '@emotion/styled';
import { theme } from 'theme';

export const ChipsContainer = styled.div({
  display: 'flex',
  alignItems: 'center',
  width: '100%',
  flexWrap: 'wrap',
  gap: '8px',
  gridColumn: '1 / -1',
});

interface ChipProps {
  $selected?: boolean;
  $disabled?: boolean;
}

export const Chip = styled.button<ChipProps>(({ $selected, $disabled }) => ({
  padding: '8px 12px',
  border: '1px solid #D9D9D9',
  borderRadius: '1rem',
  backgroundColor: 'rgba(255, 241, 194, 0.098)',
  fontSize: theme.fonts.fontSizes['1'],
  fontWeight: theme.fonts.fontWeights.medium,
  fontFamily: theme.fonts.paragraph,
  cursor: 'pointer',
  transition: 'all 0.2s ease',

  '&:hover': {
    backgroundColor: '#FFF1C2',
    borderColor: '#FFF1C2',
  },

  ...($selected && {
    backgroundColor: '#FFF1C2',
    borderColor: '#FFF1C2',
    fontWeight: theme.fonts.fontWeights.semibold,
  }),
  ...($disabled && {
    opacity: 0.5,
    cursor: 'auto',
    pointerEvents: 'none',

    '&:hover': {
      backgroundColor: '#ffffff',
      borderColor: '#D9D9D9',
    },
  }),
}));
